contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newFee) public {
        // The test contract deployed c, so it is the owner and may call setFee.
        // General rule: setFee accepts exactly the fees below 30 and stores them verbatim.
        if (newFee >= 30) {
            bool reverted;
            bytes memory ret;
            (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setFee.selector, newFee));
            reverted = !ok;
            require(reverted);
            return;
        }
        c.setFee(newFee);
        assert(c.fee() == newFee && c.fee() < 30);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 newFee) public {
        bool reverted;
        try c.setFee(newFee) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(
            (newFee >= 30 && reverted) ||
            (newFee < 30 && !reverted && c.fee() == newFee)
        );
    }
}

