contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address maker, bool isCall, address baseAsset, uint256 strike, uint256 premium) public {
        require(maker != address(0));

        address[] memory emptyAddr = new address[](0);
        C.ERC20Asset[] memory empty20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory empty721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: 1 days,
            expiration: block.timestamp + 2 days,
            nonce: 0,
            whitelist: emptyAddr,
            floorTokens: emptyAddr,
            erc20Assets: empty20,
            erc721Assets: empty721
        });

        bytes32 h = c.hashOrder(order);

        // A non-maker cancel must revert.
        bool reverted;
        if (maker == address(this)) {
            reverted = false;
        } else {
            try c.cancel(order) { reverted = false; } catch { reverted = true; }
        }
        bool nonMakerReverted = reverted;

        // Non-maker cancel must not mark the order cancelled.
        if (maker != address(this)) {
            require(!c.cancelledOrders(h));
        }

        // Now cancel as the maker: temporarily change maker via a fresh order copy.
        order.maker = address(this);
        bytes32 h2 = c.hashOrder(order);
        c.cancel(order);

        assert(
            (maker == address(this) ? !nonMakerReverted : nonMakerReverted)
            && (maker == address(this) || !c.cancelledOrders(h))
            && c.cancelledOrders(h2)
            && c.cancelledOrders(h2) == c.cancelledOrders(c.hashOrder(order))
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newFee) public payable {
        // fee must be strictly less than 30 for a successful setFee
        bool reverted;
        if (newFee < 30) {
            c.setFee{value: 0}(newFee);
            reverted = false;
        } else {
            try c.setFee{value: 0}(newFee) { reverted = false; } catch { reverted = true; }
        }

        uint256 stored = c.fee();

        assert(
            (newFee < 30 ? (!reverted && stored == newFee) : (reverted && stored != newFee && stored < 30))
        );
    }
    receive() external payable {}
}

