            erc721Assets: noE721
        });
        bytes32 h = c.hashOrder(o);
        bytes32 hOpp = c.hashOppositeOrder(o);
        bytes32 hFlipped = c.hashOrder(opp);
        assert(hOpp == hFlipped && hOpp != h);
    }
    receive() external payable {}
}

