contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] memory whitelist,
        address[] memory floorTokens
    ) public {
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 oh = c.hashOrder(order);
        bytes32 oppOh = c.hashOppositeOrder(order);

        // cancel as a non-maker must revert and change nothing
        bool revertedNonMaker;
        try c.cancel(order) { revertedNonMaker = false; } catch { revertedNonMaker = true; }

        bool flagAfterNonMaker = c.cancelledOrders(oh);
        bool oppFlagAfterNonMaker = c.cancelledOrders(oppOh);

        bool revertedMaker;
        // Become the maker: since msg.sender for every call is this test contract,
        // cancelling succeeds only when maker == address(this).
        if (maker == address(this)) {
            c.cancel(order);
            revertedMaker = false;
        } else {
            revertedNonMaker = true;
            try c.cancel(order) { } catch { }
            revertedMaker = true;
        }

        bool flagAfter = c.cancelledOrders(oh);
        bool oppFlagAfter = c.cancelledOrders(oppOh);

        assert(
            revertedNonMaker &&
            !flagAfterNonMaker && !oppFlagAfterNonMaker &&
            revertedMaker &&
            flagAfter == (maker == address(this)) &&
            !oppFlagAfter
        );
    }
    receive() external payable {}
}

