    constructor(C _c) { c = _c; }

    function run(
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(duration < 10_000 days);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        require(!c.cancelledOrders(orderHash));

        c.cancel(order);

        bool cancelledAfter = c.cancelledOrders(orderHash);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = new bytes(0);
        bool fillReverted;
        uint256 pid;
        // top-level state-changing call wrapped by try is disallowed; use low-level call instead
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.fillOrder.selector,
                order,
                signature,
                floorAssetTokenIds
            )
        );
        fillReverted = !ok;
        pid = 0;

        assert(cancelledAfter && fillReverted);
    }

    receive() external payable {}
    fallback() external payable {}
}

